try:
    # Used ONLY to ask the kernel how much of the instruction is still sitting
    # unread in the pipe. FIONREAD on the WRITE end reports exactly that, which
    # is the one mechanical way to tell "the controller wrote it" apart from
    # "the bytes were read out of the pipe". Their absence is not worked
    # around: see wait_for_stdin_drain(), which fails closed without them.
    import struct
    import termios
except ImportError:  # pragma: no cover - this controller runs on Linux
    struct = None
    termios = None

try:
    # Used ONLY by Piece 3, to hold one exclusive lock across the whole
    # read-tail / compare-and-swap / append / verify sequence on the interview
    # journal. Its absence is not worked around: an unserialised append is
    # exactly the corruption the lock exists to prevent, so a platform without
    # it fails closed at the append rather than proceeding unlocked.
    import fcntl
except ImportError:  # pragma: no cover - this controller runs on Linux
    fcntl = None

MODE = "DESIGN-ONLY"

